**Untested functions:** `routeTask`

**Edge cases missing:**
- Empty string input → default fallback
- Task that matches multiple patterns (first-match wins, undocumented)
- Case sensitivity (regex uses `'i'` flag but `taskLower` already lowercases — double-lowered)
- Partial-word false positives (e.g. `"api"` matching in `"capital"`)

**Test skeleton:**
```js
// tests/router.test.js
const { routeTask, AGENT_CAPABILITIES } = require('../.claude/helpers/router.js');

describe('routeTask', () => {
  test('routes code tasks to coder', () => {
    const r = routeTask('implement a new feature');
    expect(r.agent).toBe('coder');
    expect(r.confidence).toBe(0.8);
  });

  test('routes test tasks to tester', () => {
    expect(routeTask('write unit tests for auth').agent).toBe('tester');
  });

  test('routes API tasks to backend-dev', () => {
    expect(routeTask('add a new API endpoint').agent).toBe('backend-dev');
  });

  test('defaults to coder on unknown input', () => {
    const r = routeTask('do something vague');
    expect(r.agent).toBe('coder');
    expect(r.confidence).toBe(0.5);
    expect(r.reason).toMatch(/default/i);
  });

  test('handles empty string without throwing', () => {
    expect(() => routeTask('')).not.toThrow();
    expect(routeTask('').agent).toBe('coder');
  });

  test('all routed agents exist in AGENT_CAPABILITIES', () => {
    const agents = Object.values(require('../.claude/helpers/router.js').TASK_PATTERNS);
    for (const agent of agents) {
      expect(AGENT_CAPABILITIES).toHaveProperty(agent);
    }
  });
});
