**Untested functions:** `get`, `set`, `delete`, `clear`, `keys`, `loadMemory`

**Edge cases missing:**
- `set()` with no key → logs error, returns undefined (no throw)
- `delete()` with no key → same
- `keys()` filters internal `_updated` key
- `loadMemory()` with corrupted JSON → returns `{}` silently
- `get(undefined)` → returns entire memory object, not `undefined`

**Test skeleton:**
```js
// tests/memory.test.js
const fs = require('fs');
const os = require('os');
const path = require('path');

// Redirect cwd to a temp dir so tests don't touch real data
let tmpDir;
beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'cf-mem-test-'));
  jest.spyOn(process, 'cwd').mockReturnValue(tmpDir);
  jest.resetModules(); // re-require with new cwd
});
afterEach(() => fs.rmSync(tmpDir, { recursive: true, force: true }));

function getCommands() {
  return require('../.claude/helpers/memory.js');
}

describe('memory.set / get', () => {
  test('set stores value and get retrieves it', () => {
    const { set, get } = getCommands();
    set('foo', 'bar');
    expect(get('foo')).toBe('bar');
  });

  test('get with no key returns full memory object', () => {
    const { set, get } = getCommands();
    set('a', '1');
    const all = get(undefined);
    expect(all).toMatchObject({ a: '1' });
  });

  test('set without key logs error and does not write', () => {
    const { set } = getCommands();
    const spy = jest.spyOn(console, 'error').mockImplementation(() => {});
    set(undefined, 'value');
    expect(spy).toHaveBeenCalled();
    spy.mockRestore();
  });
});

describe('memory.delete', () => {
  test('removes an existing key', () => {
    const { set, delete: del, get } = getCommands();
    set('x', 'y');
    del('x');
    expect(get('x')).toBeUndefined();
  });

  test('delete with no key logs error', () => {
    const { delete: del } = getCommands();
    const spy = jest.spyOn(console, 'error').mockImplementation(() => {});
    del(undefined);
    expect(spy).toHaveBeenCalled();
    spy.mockRestore();
  });
});

describe('memory.keys', () => {
  test('excludes internal _updated key', () => {
    const { set, keys } = getCommands();
    set('visible', 'v');
    const result = keys();
    expect(result).toContain('visible');
    expect(result).not.toContain('_updated');
  });

  test('returns empty array on empty store', () => {
    const { keys } = getCommands();
    expect(keys()).toEqual([]);
  });
});

describe('memory.clear', () => {
  test('clears all stored keys', () => {
    const { set, clear, keys } = getCommands();
    set('a', '1');
    set('b', '2');
    clear();
    expect(keys()).toEqual([]);
  });
});

describe('loadMemory — corrupt file', () => {
  test('returns {} when memory.json is corrupted', () => {
    const { set } = getCommands();
    // Write garbage into the memory file
    const memFile = path.join(tmpDir, '.claude-flow', 'data', 'memory.json');
    fs.mkdirSync(path.dirname(memFile), { recursive: true });
    fs.writeFileSync(memFile, 'NOT_JSON');
    jest.resetModules();
    const { get } = require('../.claude/helpers/memory.js');
    expect(get(undefined)).toBeNull(); // no file in cwd variant
  });
});
```

