**Untested functions:** `start`, `restore`, `end`, `status`, `update`, `get`, `metric`

**Edge cases missing:**
- `metric('nonExistentMetric')` → session unchanged (guard `!== undefined`)
- `end()` calculates `duration` correctly from `startedAt`
- `end()` archives to `session-<id>.json` and removes `current.json`
- `restore()` when no session file → returns `null`
- `get('key')` vs `get()` (full context vs single key)

**Test skeleton:**
```js
// tests/session.test.js
const fs = require('fs');
const os = require('os');
const path = require('path');

let tmpDir;
beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'cf-sess-test-'));
  jest.spyOn(process, 'cwd').mockReturnValue(tmpDir);
  jest.resetModules();
});
afterEach(() => fs.rmSync(tmpDir, { recursive: true, force: true }));

function cmds() { return require('../.claude/helpers/session.js'); }

describe('session.start', () => {
  test('creates current.json with expected shape', () => {
    const s = cmds().start();
    expect(s.id).toMatch(/^session-\d+$/);
    expect(s.metrics).toEqual({ edits: 0, commands: 0, tasks: 0, errors: 0 });
    const sessionFile = path.join(tmpDir, '.claude-flow', 'sessions', 'current.json');
    expect(fs.existsSync(sessionFile)).toBe(true);
  });
});

describe('session.restore', () => {
  test('returns null when no session exists', () => {
    expect(cmds().restore()).toBeNull();
  });

  test('adds restoredAt to existing session', () => {
    cmds().start();
    jest.resetModules();
    const s = require('../.claude/helpers/session.js').restore();
    expect(s.restoredAt).toBeDefined();
  });
});

describe('session.end', () => {
  test('returns null when no session exists', () => {
    expect(cmds().end()).toBeNull();
  });

  test('archives session and removes current.json', () => {
    const started = cmds().start();
    jest.resetModules();
    const { end } = require('../.claude/helpers/session.js');
    const sessionDir = path.join(tmpDir, '.claude-flow', 'sessions');
    const currentFile = path.join(sessionDir, 'current.json');
    end();
    expect(fs.existsSync(currentFile)).toBe(false);
    expect(fs.existsSync(path.join(sessionDir, `${started.id}.json`))).toBe(true);
  });

  test('duration is non-negative', () => {
    cmds().start();
    jest.resetModules();
    const ended = require('../.claude/helpers/session.js').end();
    expect(ended.duration).toBeGreaterThanOrEqual(0);
  });
});

describe('session.metric', () => {
  test('increments a valid metric', () => {
    cmds().start();
    jest.resetModules();
    const { metric } = require('../.claude/helpers/session.js');
    const s = metric('edits');
    expect(s.metrics.edits).toBe(1);
  });

  test('does not mutate session for unknown metric key', () => {
    cmds().start();
    jest.resetModules();
    const { metric } = require('../.claude/helpers/session.js');
    const before = require('../.claude/helpers/session.js').status();
    metric('unknownKey');
    const after = require('../.claude/helpers/session.js').status();
    expect(after.metrics).toEqual(before.metrics);
  });
});
