beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'cf-intel-test-'));
  jest.spyOn(process, 'cwd').mockReturnValue(tmpDir);
  jest.resetModules();
});
afterEach(() => fs.rmSync(tmpDir, { recursive: true, force: true }));

// Expose internal helpers via a re-export shim or test the module directly
// (assumes intelligence.cjs can be required without side effects when not main)
const intel = () => {
  jest.resetModules();
  return require('../.claude/helpers/intelligence.cjs');
};

// ── Pure function tests ───────────────────────────────────────────────────────

describe('tokenize (via trigrams integration)', () => {
  test('removes stop words', () => {
    const mod = intel();
    // Access via internal — wrap init to expose tokenize if needed
    // Or test indirectly through getContext behavior
  });
});

describe('jaccardSimilarity edge cases', () => {
  // jaccardSimilarity is internal; test indirectly via buildEdges similarity output
  test('identical entries in same category get similarity edge', () => {
    // seed a store with two near-identical entries
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    const store = [
      { id: 'a', namespace: 'test', content: 'authentication login password security', createdAt: Date.now() },
      { id: 'b', namespace: 'test', content: 'authentication login password security', createdAt: Date.now() },
    ];
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify(store));
    const { init } = intel();
    const result = init();
    // Identical content → Jaccard = 1.0 > 0.3 → 1 similarity edge
    expect(result.edges).toBeGreaterThanOrEqual(1);
  });
