  test('entries with same content but different IDs are collapsed to 1', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    const text = 'exactly the same content string here for testing';
    const store = [
      { id: 'p', content: text },
      { id: 'q', content: text }, // different ID, same content
    ];
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify(store));
    const { init } = intel();
    const result = init();
    expect(result.nodes).toBe(1);
  });

  test('whitespace-normalized content is treated as identical', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    const store = [
      { id: 'r', content: 'hello   world' },
      { id: 's', content: 'hello world' }, // same after normalization
    ];
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify(store));
    const { init } = intel();
    const result = init();
    expect(result.nodes).toBe(1);
  });
});

describe('computePageRank', () => {
  test('returns empty object for empty graph', () => {
    // Tested via init() with empty store and no MEMORY.md
    const { init } = intel();
    const result = init();
    expect(result.nodes).toBe(0);
    expect(result.message).toMatch(/No memory/);
  });

  test('ranks sum close to 1.0 for connected graph', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    const store = Array.from({ length: 5 }, (_, i) => ({
      id: `n${i}`,
      content: `entry number ${i} about routing agents tasks`,
      namespace: 'test',
      createdAt: Date.now(),
    }));
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify(store));
    const { init } = intel();
    init();
    const graph = JSON.parse(fs.readFileSync(path.join(dataDir, 'graph-state.json'), 'utf-8'));
    const sum = Object.values(graph.pageRanks).reduce((s, v) => s + v, 0);
    expect(sum).toBeCloseTo(1.0, 1); // within 0.1
  });
});

describe('readJSON — 10MB size guard', () => {
  test('returns null for files exceeding MAX_DATA_FILE_SIZE', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    // Write a large file to the store path
    const bigFile = path.join(dataDir, 'auto-memory-store.json');
    const chunk = Buffer.alloc(1024 * 1024, 'x'); // 1MB chunk
    const fd = fs.openSync(bigFile, 'w');
    for (let i = 0; i < 11; i++) fs.writeSync(fd, chunk); // 11MB
    fs.closeSync(fd);
    const { init } = intel();
    // init should skip the oversized file and return no-entries result
    const result = init();
    expect(result.nodes).toBe(0);
  });
});

describe('consolidate — pending insights', () => {
  test('promotes files edited 3+ times to insights store', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    const store = [{ id: 'seed', content: 'seed entry', namespace: 'core', createdAt: Date.now() }];
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify(store));
    // Write 3 edit events for the same file
    const lines = Array(3).fill(JSON.stringify({ type: 'edit', file: '/src/hotpath.js', timestamp: Date.now() }));
    fs.writeFileSync(path.join(dataDir, 'pending-insights.jsonl'), lines.join('\n') + '\n');
    const { consolidate } = intel();
    const result = consolidate();
    expect(result.newEntries).toBe(1);
  });

  test('does not duplicate insight for the same file across calls', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    const existingInsight = [{
      id: 'insight-existing',
      key: 'frequent-edit-hotpath.js',
      content: 'File /src/hotpath.js was edited 3 times',
      metadata: { sourceFile: '/src/hotpath.js', autoGenerated: true },
      namespace: 'insights',
      createdAt: Date.now(),
    }];
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify(existingInsight));
    const lines = Array(3).fill(JSON.stringify({ type: 'edit', file: '/src/hotpath.js', timestamp: Date.now() }));
    fs.writeFileSync(path.join(dataDir, 'pending-insights.jsonl'), lines.join('\n') + '\n');
    const { consolidate } = intel();
    const result = consolidate();
    expect(result.newEntries).toBe(0); // already exists
  });
});

describe('getContext — threshold and session state', () => {
  test('returns null when prompt is empty', () => {
    const { getContext } = intel();
    expect(getContext('')).toBeNull();
    expect(getContext(null)).toBeNull();
  });

  test('returns null when no ranked entries exist', () => {
    const { getContext } = intel();
    expect(getContext('some task')).toBeNull();
  });

  test('returns formatted string when matching entries exist', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    const store = [
      { id: 'e1', content: 'authentication login security password', namespace: 'core', createdAt: Date.now() },
    ];
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify(store));
    const mod = intel();
    mod.init(); // build ranked cache
    jest.resetModules();
    const { getContext } = require('../.claude/helpers/intelligence.cjs');
    const ctx = getContext('implement authentication login');
    expect(ctx).toMatch(/\[INTELLIGENCE\]/);
  });
});
