**Untested functions:** `safeRequire`, `runWithTimeout`, `readStdin`, handler: `pre-bash`

**Edge cases missing:**
- `pre-bash` detects all 4 dangerous command strings and exits with code 1
- `pre-bash` passes through safe commands with `[OK]`
- `runWithTimeout` resolves `null` when function exceeds 3s timeout
- `safeRequire` suppresses console output from helper modules on require
- `readStdin` resolves immediately when stdin is a TTY

**Test skeleton:**
```js
// tests/hook-handler.test.js
const { spawnSync } = require('child_process');
const path = require('path');

const HANDLER = path.join(__dirname, '../.claude/helpers/hook-handler.cjs');

function runHandler(command, stdinData = '') {
  const result = spawnSync(
    process.execPath,
    [HANDLER, command],
    {
      input: stdinData,
      encoding: 'utf-8',
      timeout: 8000,
    }
  );
  return result;
}

describe('pre-bash handler', () => {
  test('blocks "rm -rf /" and exits 0 (hooks must not crash Claude Code)', () => {
    const input = JSON.stringify({ command: 'rm -rf /' });
    const result = runHandler('pre-bash', input);
    // Hook always exits 0 (process.exitCode = 0 at top of file) but logs BLOCKED
    expect(result.stderr).toMatch(/BLOCKED/);
  });

  test('passes safe commands without blocking', () => {
    const input = JSON.stringify({ command: 'ls -la' });
    const result = runHandler('pre-bash', input);
    expect(result.stdout).toMatch(/\[OK\]/);
  });

  test('blocks fork bomb', () => {
    const input = JSON.stringify({ command: ':(){:|:&};:' });
    const result = runHandler('pre-bash', input);
    expect(result.stderr).toMatch(/BLOCKED/);
  });

  test('blocks "format c:" (Windows)', () => {
    const input = JSON.stringify({ command: 'format c:' });
    const result = runHandler('pre-bash', input);
    expect(result.stderr).toMatch(/BLOCKED/);
  });
});

describe('route handler', () => {
  test('outputs routing recommendation box', () => {
    const input = JSON.stringify({ prompt: 'implement authentication' });
    const result = runHandler('route', input);
    expect(result.stdout).toMatch(/Primary Recommendation/);
    expect(result.stdout).toMatch(/Agent:/);
  });

  test('handles missing prompt gracefully', () => {
    const result = runHandler('route', '{}');
    expect(result.stdout).toMatch(/\[OK\]|\[INFO\]/);
  });
});

describe('unknown command', () => {
  test('outputs [OK] without crashing', () => {
    const result = runHandler('unknown-command-xyz');
    expect(result.stdout).toMatch(/\[OK\]/);
    expect(result.status).toBe(0);
  });
});

describe('malformed stdin JSON', () => {
  test('does not crash on non-JSON input', () => {
    const result = runHandler('route', 'NOT JSON AT ALL');
    expect(result.status).toBe(0);
  });
});
