  return spawnSync(process.execPath, [HANDLER, cmd], {
    input,
    encoding: 'utf-8',
    timeout: 10000,
    env: { ...process.env, CF_CWD: tmpDir },
    cwd: tmpDir,
  });
}

describe('session lifecycle: restore → route → post-edit → session-end', () => {
  test('completes full hook pipeline without errors', () => {
    const restore = hook('session-restore', '{}');
    expect(restore.status).toBe(0);

    const route = hook('route', JSON.stringify({ prompt: 'implement login feature' }));
    expect(route.stdout).toMatch(/coder|backend-dev/);

    const edit = hook('post-edit', JSON.stringify({ file_path: '/src/auth.js' }));
    expect(edit.status).toBe(0);

    const end = hook('session-end', '{}');
    expect(end.status).toBe(0);
  });
});

describe('intelligence init → getContext roundtrip', () => {
  test('getContext returns matches after init', () => {
    // Seed store
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    const store = [
      { id: 'auth1', content: 'authentication JWT token session security', namespace: 'core', createdAt: Date.now() },
    ];
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify(store));

    // Run init via CLI
    const initResult = spawnSync(process.execPath,
      [path.join(__dirname, '../.claude/helpers/intelligence.cjs'), 'init'],
      { encoding: 'utf-8', cwd: tmpDir, timeout: 10000 }
    );
    expect(JSON.parse(initResult.stdout).nodes).toBe(1);

    // getContext via module
    jest.resetModules();
    jest.spyOn(process, 'cwd').mockReturnValue(tmpDir);
    const { getContext } = require('../.claude/helpers/intelligence.cjs');
    const ctx = getContext('add authentication token validation');
    expect(ctx).toMatch(/\[INTELLIGENCE\]/);
  });
});
